const SYSTEM_META_PREFIXES=['inspection-profile:','inspection-profile-receipt:','file-content:','inspection-case:','inspection-case-receipt:','inspection-case-file:','inspection-report-action:','inspection-contact-card:','inspection-reminder-policy:','inspection-reminder-run:','inspection-reminder-scan:','inspection-reminder-draft:','inspection-reminder-day:','inspection-reminder-audit:','inspection-email-event:'];
const BUCKET='stickney-fire-inspections-backups',PILOT='stickney-fire-inspections-pilot',ESO='stickney-fire-inspections-eso',PORTAL='firehouse-portal',PAGE=8;
