function canonical(value:unknown):string{return Array.isArray(value)?'['+value.map(canonical).join(',')+']':backupObject(value)?'{'+Object.keys(value).sort().map(key=>json(key)+':'+canonical(value[key])).join(',')+'}':json(value);}
