const jobKey=(c:NativeBackupContext,jobId:string,part:string)=>c.department+'/'+id(jobId)+'/'+part;
function publicJob(job:Job){return{id:job.id,kind:job.kind,state:job.state,createdAt:job.created_at,updatedAt:job.updated_at,summary:parse<Summary>(job.summary),error:job.error,manifestHash:job.manifest_hash};}
async function job(c:NativeBackupContext,jobId:string){const value=await c.db.prepare('SELECT * FROM fire_inspection_backup_jobs WHERE department_id=? AND id=?').bind(c.department,id(jobId)).first<Job>();if(!value)throw fail('This backup job is not available in your department.',404);return value;}
async function update(c:NativeBackupContext,j:Job,config:Config,summary:Summary,state=j.state){await c.db.prepare(`UPDATE fire_inspection_backup_jobs SET config=${unhex},summary=${unhex},state=?,updated_at=?,error=NULL WHERE department_id=? AND id=? AND state=? AND lease_token=?`).bind(hex(json(config)),hex(json(summary)),state,at(),c.department,j.id,j.state,j.lease_token).run();}
async function parts(c:NativeBackupContext,j:Job){return(await c.db.prepare('SELECT * FROM fire_inspection_backup_entries WHERE department_id=? AND job_id=? ORDER BY path').bind(c.department,j.id).all<Part>()).results;}
async function rows(c:NativeBackupContext,j:Job,dataset:string,after='',limit=PAGE){return(await c.db.prepare('SELECT dataset,entry_key,row_json,plan_status,applied FROM fire_inspection_backup_rows WHERE department_id=? AND job_id=? AND dataset=? AND entry_key>? ORDER BY entry_key LIMIT ?').bind(c.department,j.id,dataset,after,limit).all<StoredRow>()).results;}
async function readBytes(c:NativeBackupContext,bucket:string,key:string,expectedSize?:number,expectedHash?:string){const blob=await c.storage.read(bucket,key);if(!blob||blob.size<1||blob.size>MAX_BACKUP_PART_BYTES||expectedSize!==undefined&&blob.size!==expectedSize)throw fail('A required private file is unavailable or changed size. Repair it before completing this backup.');const bytes=new Uint8Array(await blob.arrayBuffer());if(expectedHash&&await hash(bytes)!==expectedHash)throw fail('A required private file failed its checksum. The package remains incomplete.');return bytes;}
async function writeVerified(c:NativeBackupContext,key:string,bytes:Uint8Array,expectedHash:string){await c.storage.write(BUCKET,key,bytes);await readBytes(c,BUCKET,key,bytes.byteLength,expectedHash);}
async function savePart(c:NativeBackupContext,j:Job,entry:BackupEntry,bytes:Uint8Array){const key=jobKey(c,j.id,'parts/'+entry.sha256);await writeVerified(c,key,bytes,entry.sha256);await c.db.prepare(`INSERT INTO fire_inspection_backup_entries(department_id,job_id,path,part_key,size_bytes,sha256,crc32,details) VALUES(?,?,?,?,?,?,?,${unhex}) ON CONFLICT(department_id,job_id,path) DO NOTHING`).bind(c.department,j.id,entry.path,key,entry.size,entry.sha256,entry.crc32,hex(json(entry))).run();const saved=await c.db.prepare('SELECT sha256,size_bytes FROM fire_inspection_backup_entries WHERE department_id=? AND job_id=? AND path=?').bind(c.department,j.id,entry.path).first<{sha256:string;size_bytes:number}>();if(!saved||saved.sha256!==entry.sha256||saved.size_bytes!==entry.size)throw fail('The saved backup part conflicts with an earlier response. Keep this job for review.');}
