  if(!dataset){config.phase='references';config.index=0;config.after='';}else{const selected=await rows(c,j,dataset.name,config.after);if(!selected.length){config.index++;config.after='';config.part=0;}else{const data=encode.encode(json({dataset:dataset.name,rows:selected.map(r=>parse(r.row_json))}));if(data.length>8*1024*1024)throw fail('A metadata part exceeds its bounded processing limit.');await savePart(c,j,{path:`metadata/${dataset.name}/${String(config.part).padStart(8,'0')}.json`,kind:'dataset',dataset:dataset.name,size:data.length,sha256:await hash(data),crc32:backupCrc32(data)},data);config.after=selected.at(-1)!.entry_key;config.part++;summary.rows+=selected.length;}}
