async function validateRestoreColumns(c:NativeBackupContext,j:Job){const config=parse<Config>(j.config);for(const d of config.datasets.filter(d=>d.restore==='missing-only')){const columns=(await c.db.prepare("SELECT column_name FROM information_schema.columns WHERE table_schema='firehouse' AND table_name=?").bind(d.name).all<{column_name:string}>()).results.map(r=>r.column_name).sort();if(!columns.length)throw fail('A native recovery table is unavailable. Update the database before applying recovery.');const selected=await rows(c,j,d.name,'',1);if(selected.length&&!equal(Object.keys(parse<Row>(selected[0].row_json)).sort(),columns))throw fail('The backup contains a different native schema. Use a compatible version before recovering these rows.');}}
