export async function beginNativeRestoreApply(c:NativeBackupContext,jobId:string,confirmation:unknown){const j=await job(c,jobId);if(j.state==='applying'||j.state==='complete')return nativeBackupStatus(c,jobId);if(j.kind!=='restore'||j.state!=='preview'||confirmation!=='RESTORE MISSING DATA')throw fail('Review the preview and type RESTORE MISSING DATA before recovering.',409);const config=parse<Config>(j.config);config.phase='objects';config.after='';config.index=0;const summary=parse<Summary>(j.summary);summary.deliveryHeld=true;await update(c,j,config,summary,'applying');return nativeBackupStatus(c,jobId);}
